    "Name": "Sidenav",
    "Key": "Common",
    "ResourceKey": "Common",
    "Script": "Sidenav = {
    init: async function(app, container) {
        app = app || session.app;
        container = container || $(".component[name=Sidenav]");
        var host = $("[name=documentationTree]", container);
        var result = await api.get("ContentManagement/Page?$filter=AppId eq " + app.Id + " and ShowOnMenus eq true&$orderby=Order asc&$expand=PageInfo");
        var pages = (result.value || []).filter(page => page.Path === "Documentation" || page.Path.startsWith("Documentation/"));
        var currentPath = window.location.pathname.replace(/^\//, "");
        host.html(Sidenav.renderTree(pages, "Documentation", currentPath, 0));
    },

    renderTree: function(pages, rootPath, currentPath, depth) {
        var children = pages
            .filter(page => Sidenav.parentPath(page.Path) === rootPath)
            .sort((left, right) => (left.Order || 0) - (right.Order || 0) || Sidenav.title(left).localeCompare(Sidenav.title(right)));

        if (children.length === 0) return "";

        var items = children.map(page => {
            var active = page.Path === currentPath ? " active" : "";
            var currentBranch = currentPath === page.Path || currentPath.startsWith(page.Path + "/");
            var childTree = depth < 1 || currentBranch
                ? Sidenav.renderTree(pages, page.Path, currentPath, depth + 1)
                : "";
            var icon = active ? "k-i-arrow-right" : currentBranch ? "k-i-folder-open" : "k-i-file";
            return '<li class="nav-item"><span class="k-icon ' + icon + '"></span><a class="nav-link' + active + '" href="/' + page.Path + '">' + Sidenav.escapeHtml(Sidenav.title(page)) + '</a>' + childTree + '</li>';
        }).join("");

        return '<ul class="navbar-nav submenu">' + items + '</ul>';
    },

    parentPath: function(path) {
        var index = path.lastIndexOf("/");
        return index < 0 ? "" : path.substring(0, index);
    },

    title: function(page) {
        var info = (page.PageInfo || []).filter(item => item.CultureId === session.culture)[0]
            || (page.PageInfo || []).filter(item => item.CultureId === "")[0];
        return (info && info.Title) || page.Name;
    },

    escapeHtml: function(value) {
        return $("<div></div>").text(value || "").html();
    }
}",
